import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Naive CUDA source for 2D convolution
conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int in_height,
    const int in_width,
    const int out_channels,
    const int kernel_size,
    const int stride,
    const int padding,
    const int dilation,
    const int out_height,
    const int out_width,
    const bool has_bias
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_channels * out_height * out_width) {
        return;
    }

    // Decompose linear index
    int temp = idx;
    int ow = temp % out_width;
    temp /= out_width;
    int oh = temp % out_height;
    temp /= out_height;
    int oc = temp % out_channels;
    temp /= out_channels;
    int b = temp;

    float val = 0.0f;

    // Compute convolution
    for (int ic = 0; ic < in_channels; ic++) {
        for (int kh = 0; kh < kernel_size; kh++) {
            for (int kw = 0; kw < kernel_size; kw++) {
                int ih = oh * stride - padding + kh * dilation;
                int iw = ow * stride - padding + kw * dilation;
                if (ih >= 0 && ih < in_height && iw >= 0 && iw < in_width) {
                    int in_index = ((b * in_channels + ic) * in_height + ih) * in_width + iw;
                    int w_index = ((oc * in_channels + ic) * kernel_size + kh) * kernel_size + kw;
                    val += input[in_index] * weight[w_index];
                }
            }
        }
    }

    if (has_bias) {
        val += bias[oc];
    }

    int out_index = ((b * out_channels + oc) * out_height + oh) * out_width + ow;
    output[out_index] = val;
}

torch::Tensor conv2d_naive_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation
) {
    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto in_height = input.size(2);
    const auto in_width = input.size(3);

    const auto out_channels = weight.size(0);
    const auto kernel_size = weight.size(2);

    // Calculate output spatial dimensions
    int out_height = (in_height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_width = (in_width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto options = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({batch_size, out_channels, out_height, out_width}, options);

    bool has_bias = (bias.numel() > 0);

    int total = batch_size * out_channels * out_height * out_width;
    const int block_size = 256;
    const int grid_size = (total + block_size - 1) / block_size;

    conv2d_forward_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        in_height,
        in_width,
        out_channels,
        kernel_size,
        stride,
        padding,
        dilation,
        out_height,
        out_width,
        has_bias
    );

    return output;
}
""".strip()

conv2d_cpp = r"""
torch::Tensor conv2d_naive_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation
);
"""

# Compile the custom CUDA operator
conv2d_naive = load_inline(
    name="conv2d_naive",
    cpp_sources=conv2d_cpp,
    cuda_sources=conv2d_source,
    functions=["conv2d_naive_forward"],
    verbose=False,
    extra_cflags=["-O2"],
    extra_ldflags=[],
)

class ModelNew(nn.Module):
    """
    Custom 2D convolution using a naive CUDA kernel.
    """
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        dilation: int = 1,
        groups: int = 1,
        bias: bool = False
    ):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        # Define parameters similar to nn.Conv2d
        self.weight = nn.Parameter(
            torch.randn(out_channels, in_channels, kernel_size, kernel_size)
        )
        if bias:
            self.bias = nn.Parameter(torch.randn(out_channels))
        else:
            self.bias = nn.Parameter(torch.zeros(out_channels), requires_grad=False)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return conv2d_naive.conv2d_naive_forward(
            x,
            self.weight,
            self.bias,
            self.stride,
            self.padding,
            self.dilation
        )
